#!/usr/bin/env node
/**
 * Builds the SQL files you paste into the Supabase SQL editor.
 *
 * The migrations and seeds are the source of truth; this only concatenates them
 * in order, with a header naming each file, so a project can be created without
 * the Supabase CLI. Re-running the output is safe: every migration creates or
 * replaces, and the seeds upsert by their natural key.
 *
 *   node scripts/build-migration-bundle.mjs
 *
 * Output:
 *   supabase/apply-1-schema.sql      migrations (schema, functions, RLS, storage)
 *   supabase/apply-2-reference.sql   applicant categories, support needs, programme
 *   supabase/apply-3-locations.sql   Nigerian geography (37 states, 774 LGAs, 8,809 wards)
 */

import { readFile, writeFile, readdir } from 'node:fs/promises';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const migrationsDir = path.join(root, 'supabase', 'migrations');
const seedDir = path.join(root, 'supabase', 'seed');

const HEADER = (title, files) => `-- ============================================================================
-- GIZMO DAN KAITA OFFICE PLUS — ${title}
--
-- Generated by scripts/build-migration-bundle.mjs. Do not edit by hand:
-- edit the files under supabase/ and regenerate.
--
-- Run the three bundles in order, in the Supabase SQL editor:
--   1. supabase/apply-1-schema.sql
--   2. supabase/apply-2-reference.sql
--   3. supabase/apply-3-locations.sql
--
-- Every statement is idempotent, so re-running any of them is safe.
--
-- Sources, in order:
${files.map((file) => `--   ${path.relative(root, file)}`).join('\n')}
-- ============================================================================

`;

async function bundle(title, files, outName) {
  const parts = [HEADER(title, files)];

  for (const file of files) {
    const sql = await readFile(file, 'utf8');
    parts.push(
      `\n-- ${'='.repeat(74)}\n-- ${path.relative(root, file)}\n-- ${'='.repeat(74)}\n\n`,
      sql.trimEnd(),
      '\n'
    );
  }

  const outPath = path.join(root, 'supabase', outName);
  await writeFile(outPath, parts.join(''));
  const bytes = (await readFile(outPath)).length;
  console.log(`  ${outName.padEnd(28)} ${(bytes / 1024).toFixed(0)} KB`);
}

const migrationFiles = (await readdir(migrationsDir))
  .filter((name) => name.endsWith('.sql'))
  .sort()
  .map((name) => path.join(migrationsDir, name));

const referenceSeed = path.join(seedDir, '001_reference_data.sql');
const locationSeed = path.join(seedDir, '002_locations_nigeria.sql');

console.log('Building SQL bundles from supabase/migrations and supabase/seed:\n');
await bundle('schema, functions, Row Level Security and storage', migrationFiles, 'apply-1-schema.sql');
await bundle('reference data (categories, support needs, document types, programme)', [referenceSeed], 'apply-2-reference.sql');
await bundle('Nigerian geography (states, local government areas, wards)', [locationSeed], 'apply-3-locations.sql');
console.log('\nPaste them into the Supabase SQL editor in numeric order.');
